import { jsonLd, publicPageMetadata, siteDescription, siteUrl } from "@/lib/seo";

export const metadata = publicPageMetadata("Find your next opportunity, together", siteDescription, "/");

async function getOpportunities(): Promise<Opportunity[]> {
  try {
    const base = (process.env.API_URL || process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api").replace(/\/$/, "");
    const response = await fetch(`${base}/opportunities/`, { next: { revalidate: 300 }, signal: AbortSignal.timeout(5000) });
    if (!response.ok) return [];
    const data = await response.json() as { results: Opportunity[] };
    return data.results.filter((item) => !item.deadline || new Date(item.deadline).getTime() > Date.now()).slice(0, 3);
  } catch { return []; }
}

